//! Base game content (core set) = the classic rule set.
//! Lives here (§28: content knows classic-content), compiled by core (§29).
//!
//! The source of truth is classic/assets/rules/classic/*.ron (generated by the importer from
//! classic/docs/classic). core_rules() parses them via include_str!: deterministic,
//! without the FS (web and tests). The former small core.ron is frozen as a test
//! fixture (`crate::legacy`).

use classic_rules::rules::source::SourceRules;

/// The default game rule set: the classic set (all tables, including
/// nations). Id is the position in a table sorted by key: code
/// looks up units and buildings by key, not by index.
pub fn core_rules() -> SourceRules {
    crate::classic::classic_rules()
}

#[cfg(test)]
mod tests {
use classic_rules::ClassicGame;
    use super::*;
    use classic_rules::rules::compile_rules;

    #[test]
    fn core_content_is_the_classic_ruleset() {
        let compiled = compile_rules(core_rules()).unwrap();
        assert_eq!(compiled.technologies.len(), 81);
        assert_eq!(compiled.units.len(), 82 + 59);
        assert_eq!(compiled.nations.len(), 43);
        let unit = |k: &str| compiled.units.iter().find(|u| u.key == k).unwrap();
        assert!(unit("core:unit/settler").founder);
        assert!(unit("core:unit/worker").builder);
        assert!(!unit("core:unit/warrior").founder);
        let england = compiled
            .nations
            .iter()
            .find(|c| c.key == "core:nation/england")
            .unwrap();
        assert_eq!(
            england.start_bias,
            classic_rules::rules::source::StartBias::Coastal
        );
    }

    /// Every classic leader has its own personality (none is neutral), on the
    /// 0–10 scale; a row naming a nation twice or a value off the
    /// scale is refused.
    #[test]
    fn every_leader_has_a_personality_on_the_scale() {
        use classic_rules::rules::content::Personality;
        let compiled = compile_rules(core_rules()).unwrap();
        let tables = &compiled.module;
        assert_eq!(tables.personalities.len(), compiled.nations.len());
        for (nation, def) in compiled.nations.iter().enumerate() {
            let personality = tables.personality(nation as u8);
            assert_ne!(personality, Personality::NEUTRAL, "{}", def.key);
            assert!(personality.values().iter().all(|v| *v <= Personality::MAX), "{}", def.key);
        }
        let mongolia = compiled.nations.iter().position(|c| c.key == "core:nation/mongolia").unwrap();
        assert_eq!(tables.personality(mongolia as u8).aggression, 10);

        let mut twice = core_rules();
        let first = twice.module.personalities[0].clone();
        twice.module.personalities.push(first);
        assert!(compile_rules(twice).is_err(), "a nation with two personalities");
        let mut off_scale = core_rules();
        off_scale.module.personalities[0].personality.gold = 11;
        assert!(compile_rules(off_scale).is_err(), "a value above the scale");
    }

    #[test]
    fn core_building_tech_unlocks_are_symmetric() {
        // A building's required_tech <-> a tech's unlocks_buildings: strictly a mirror,
        // otherwise the HUD shows a foreign lock or a building becomes unavailable.
        let compiled = compile_rules(core_rules()).unwrap();
        for (i, b) in compiled.buildings.iter().enumerate() {
            if let Some(t) = b.required_tech {
                let tech = &compiled.technologies[t.0 as usize];
                assert!(
                    tech.unlocks_buildings
                        .contains(&classic_rules::ids::BuildingKindId(i as u16)),
                    "{} must be listed in unlocks of {}",
                    b.key,
                    tech.key
                );
            }
        }
        for tech in &compiled.technologies {
            for u in &tech.unlocks_buildings {
                let b = &compiled.buildings[u.0 as usize];
                let required = b
                    .required_tech
                    .map(|t| compiled.technologies[t.0 as usize].key.as_str());
                assert_eq!(
                    required,
                    Some(tech.key.as_str()),
                    "{} unlocks {}, but that building requires another tech",
                    tech.key,
                    b.key
                );
            }
        }
    }

    #[test]
    fn core_free_monument_builds_while_library_stays_locked() {
        // Real content end to end: a monument (no tech) gets built,
        // a library without writing is an honest refusal and is not completed.
        use classic_rules::ids::{BuildingKindId, PlayerId, ProductionItem};
        use classic_rules::math::HexCoord;
        use classic_rules::{Command, GameConfig, GameState};

        let rules = compile_rules(core_rules()).unwrap();
        let idx = |k: &str| -> u16 {
            rules
                .buildings
                .iter()
                .position(|b| b.key == k)
                .unwrap_or_else(|| panic!("building {k} must exist")) as u16
        };
        let monument = BuildingKindId(idx("core:building/monument"));
        let library = BuildingKindId(idx("core:building/library"));
        let mut game = GameState::new(
            &rules,
            GameConfig {
                players: 2,
                width: 16,
                height: 16,
                rng_seed: 7,
            },
        );
        let dims = game.view().auth.map().dimensions;
        let t0 = dims.to_tile(HexCoord { q: 8, r: 8 }).unwrap();
        let city = game.debug_found_city(&rules, PlayerId(0), t0);

        assert!(game
            .execute(
                &rules,
                Command::EnqueueProduction {
                    player: PlayerId(0),
                    city,
                    item: ProductionItem::Building(library),
                },
            )
            .is_err());
        assert!(game
            .view()
            .auth
            .cities()
            .get(city)
            .unwrap()
            .queue
            .is_empty());

        game.execute(
            &rules,
            Command::EnqueueProduction {
                player: PlayerId(0),
                city,
                item: ProductionItem::Building(monument),
            },
        )
        .unwrap();
        for _ in 0..60 {
            game.execute(
                &rules,
                Command::EndTurn {
                    player: PlayerId(0),
                },
            )
            .unwrap();
            if game
                .view()
                .auth
                .cities()
                .get(city)
                .unwrap()
                .queue
                .is_empty()
            {
                break;
            }
        }
        let view = game.view();
        let core = view.auth.cities().get(city).unwrap();
        assert!(
            core.queue.is_empty(),
            "monument must finish within 60 turns"
        );
        assert!(core.buildings.contains(&monument));
        assert!(!core.buildings.contains(&library), "library needs writing");
        game.validate(&rules).unwrap();
    }

    #[test]
    fn core_farm_waits_for_agriculture_then_builds() {
        // Real content: a farm is closed without agriculture, after the tech
        // a worker builds it in 7 turns and the city gets +1F.
        use classic_rules::ids::{ImprovementId, PlayerId, TechId, UnitKindId};
        use classic_rules::math::HexCoord;
        use classic_rules::{Command, GameConfig, GameState};

        let rules = compile_rules(core_rules()).unwrap();
        let idx = |k: &str| -> u16 {
            rules
                .improvements
                .iter()
                .position(|i| i.key == k)
                .unwrap_or_else(|| panic!("improvement {k} must exist")) as u16
        };
        let tid = |k: &str| -> TechId {
            TechId(
                rules
                    .technologies
                    .iter()
                    .position(|t| t.key == k)
                    .unwrap_or_else(|| panic!("tech {k} must exist")) as u16,
            )
        };
        let farm = ImprovementId(idx("core:improvement/farm"));
        let worker_kind = UnitKindId(
            rules
                .units
                .iter()
                .position(|u| u.key == "core:unit/worker")
                .unwrap() as u16,
        );
        let mut game = GameState::new(
            &rules,
            GameConfig {
                players: 2,
                width: 16,
                height: 16,
                rng_seed: 7,
            },
        );
        let dims = game.view().auth.map().dimensions;
        let t0 = dims.to_tile(HexCoord { q: 8, r: 8 }).unwrap();
        let wt = dims.to_tile(HexCoord { q: 9, r: 8 }).unwrap();
        let city = game.debug_found_city(&rules, PlayerId(0), t0);
        let worker = game.debug_spawn_unit(&rules, PlayerId(0), wt, worker_kind);

        assert!(game
            .execute(
                &rules,
                Command::BuildImprovement {
                    unit: worker,
                    improvement: farm,
                },
            )
            .is_err());
        assert_eq!(game.view().auth.map().improvement(wt).unwrap(), None);

        for k in ["core:tech/agriculture"] {
            let tech = tid(k);
            game.execute(
                &rules,
                Command::ChooseTechnology {
                    player: PlayerId(0),
                    technology: tech,
                },
            )
            .unwrap();
            for _ in 0..200 {
                if game
                    .view()
                    .auth
                    .players()
                    .techs_of(PlayerId(0))
                    .contains(&tech)
                {
                    break;
                }
                game.execute(
                    &rules,
                    Command::EndTurn {
                        player: PlayerId(0),
                    },
                )
                .unwrap();
            }
            assert!(
                game.view()
                    .auth
                    .players()
                    .techs_of(PlayerId(0))
                    .contains(&tech),
                "{k} must complete"
            );
        }

        // We measure yield after the research (population growth shifts it).
        let y0 = game.derived().yields.of(city).unwrap().food;
        game.execute(
            &rules,
            Command::BuildImprovement {
                unit: worker,
                improvement: farm,
            },
        )
        .unwrap();
        for _ in 0..10 {
            if game.view().auth.map().improvement(wt).unwrap().is_some() {
                break;
            }
            game.execute(
                &rules,
                Command::EndTurn {
                    player: PlayerId(0),
                },
            )
            .unwrap();
        }
        assert_eq!(
            game.view().auth.map().improvement(wt).unwrap(),
            Some(farm),
            "farm must finish"
        );
        assert_eq!(
            game.derived().yields.of(city).unwrap().food,
            y0 + 1,
            "farm feeds +1F"
        );
        game.validate(&rules).unwrap();
    }

    #[test]
    fn core_archer_locked_until_archery_then_produces() {
        // Unit tech gate: without archery the queue is rejected ("unit locked"),
        // after two techs an archer is produced and appears on the map.
        use classic_rules::ids::{PlayerId, ProductionItem, TechId, UnitKindId};
        use classic_rules::math::HexCoord;
        use classic_rules::{Command, GameConfig, GameState};

        let rules = compile_rules(core_rules()).unwrap();
        let unit_id = |k: &str| -> UnitKindId {
            UnitKindId(
                rules
                    .units
                    .iter()
                    .position(|u| u.key == k)
                    .unwrap_or_else(|| panic!("unit {k} must exist")) as u16,
            )
        };
        let tid = |k: &str| -> TechId {
            TechId(
                rules
                    .technologies
                    .iter()
                    .position(|t| t.key == k)
                    .unwrap_or_else(|| panic!("tech {k} must exist")) as u16,
            )
        };
        let archer = unit_id("core:unit/archer");
        let mut game = GameState::new(
            &rules,
            GameConfig {
                players: 2,
                width: 16,
                height: 16,
                rng_seed: 7,
            },
        );
        let dims = game.view().auth.map().dimensions;
        let t0 = dims.to_tile(HexCoord { q: 8, r: 8 }).unwrap();
        let city = game.debug_found_city(&rules, PlayerId(0), t0);

        assert!(game
            .execute(
                &rules,
                Command::EnqueueProduction {
                    player: PlayerId(0),
                    city,
                    item: ProductionItem::Unit(archer),
                },
            )
            .is_err());
        assert!(game
            .view()
            .auth
            .cities()
            .get(city)
            .unwrap()
            .queue
            .is_empty());

        // Go through agriculture -> archery in order.
        for k in ["core:tech/agriculture", "core:tech/archery"] {
            let tech = tid(k);
            game.execute(
                &rules,
                Command::ChooseTechnology {
                    player: PlayerId(0),
                    technology: tech,
                },
            )
            .unwrap();
            for _ in 0..200 {
                if game
                    .view()
                    .auth
                    .players()
                    .techs_of(PlayerId(0))
                    .contains(&tech)
                {
                    break;
                }
                game.execute(
                    &rules,
                    Command::EndTurn {
                        player: PlayerId(0),
                    },
                )
                .unwrap();
            }
            assert!(
                game.view()
                    .auth
                    .players()
                    .techs_of(PlayerId(0))
                    .contains(&tech),
                "{k} must complete"
            );
        }

        let before = game.view().auth.units().len();
        game.execute(
            &rules,
            Command::EnqueueProduction {
                player: PlayerId(0),
                city,
                item: ProductionItem::Unit(archer),
            },
        )
        .unwrap();
        for _ in 0..80 {
            if game
                .view()
                .auth
                .cities()
                .get(city)
                .unwrap()
                .queue
                .is_empty()
            {
                break;
            }
            game.execute(
                &rules,
                Command::EndTurn {
                    player: PlayerId(0),
                },
            )
            .unwrap();
        }
        assert!(
            game.view()
                .auth
                .cities()
                .get(city)
                .unwrap()
                .queue
                .is_empty(),
            "archer must finish within 80 turns"
        );
        assert_eq!(
            game.view().auth.units().len(),
            before + 1,
            "one archer must spawn"
        );
        game.validate(&rules).unwrap();
    }

    #[test]
    fn core_wonder_globally_unique_across_cities() {
        // Wonder (pyramids): a race of two queues of one player;
        // it is built exactly once; the losing city's repeated order
        // is rejected ("wonder already built").
        use classic_rules::ids::{BuildingKindId, PlayerId, ProductionItem, TechId};
        use classic_rules::math::HexCoord;
        use classic_rules::{Command, GameConfig, GameState};

        let rules = compile_rules(core_rules()).unwrap();
        let pyramids = BuildingKindId(
            rules
                .buildings
                .iter()
                .position(|b| b.key == "core:building/pyramids")
                .unwrap() as u16,
        );
        let tid = |k: &str| -> TechId {
            TechId(
                rules
                    .technologies
                    .iter()
                    .position(|t| t.key == k)
                    .unwrap_or_else(|| panic!("tech {k} must exist")) as u16,
            )
        };
        let mut game = GameState::new(
            &rules,
            GameConfig {
                players: 2,
                width: 16,
                height: 16,
                rng_seed: 7,
            },
        );
        let dims = game.view().auth.map().dimensions;
        let t1 = dims.to_tile(HexCoord { q: 8, r: 8 }).unwrap();
        let city1 = game.debug_found_city(&rules, PlayerId(0), t1);
        // The second city: the first land at hex distance >=4 from the first
        // (otherwise the city founding validate may reject).
        let t2 = {
            let view = game.view();
            let mut found = None;
            'probe: for q in 0..16i32 {
                for r in 0..16i32 {
                    let Some(t) = dims.to_tile(HexCoord { q, r }) else {
                        continue;
                    };
                    if classic_rules::navigation::cost::enter_cost_on_map(view.auth.map(), t).is_none() {
                        continue;
                    }
                    let (dq, dr) = (q - 8, r - 8);
                    let dist = (dq.abs() + dr.abs() + (dq + dr).abs()) / 2;
                    if dist >= 4 {
                        found = Some(t);
                        break 'probe;
                    }
                }
            }
            found.expect("map must have land at distance >= 4")
        };
        let city2 = game.debug_found_city(&rules, PlayerId(0), t2);

        // Without masonry the order is rejected.
        assert!(game
            .execute(
                &rules,
                Command::EnqueueProduction {
                    player: PlayerId(0),
                    city: city2,
                    item: ProductionItem::Building(pyramids),
                },
            )
            .is_err());

        // Go through agriculture -> mining -> masonry in order.
        for k in [
            "core:tech/agriculture",
            "core:tech/mining",
            "core:tech/masonry",
        ] {
            let tech = tid(k);
            game.execute(
                &rules,
                Command::ChooseTechnology {
                    player: PlayerId(0),
                    technology: tech,
                },
            )
            .unwrap();
            for _ in 0..200 {
                if game
                    .view()
                    .auth
                    .players()
                    .techs_of(PlayerId(0))
                    .contains(&tech)
                {
                    break;
                }
                game.execute(
                    &rules,
                    Command::EndTurn {
                        player: PlayerId(0),
                    },
                )
                .unwrap();
            }
            assert!(
                game.view()
                    .auth
                    .players()
                    .techs_of(PlayerId(0))
                    .contains(&tech),
                "{k} must complete"
            );
        }

        // The Pyramids need the Liberty branch.
        let liberty = rules
            .module.policy_branches
            .iter()
            .position(|b| b.key == "core:policy/liberty")
            .unwrap();
        game.debug_grant_culture(PlayerId(0), 100);
        game.execute(
            &rules,
            Command::UnlockPolicyBranch {
                player: PlayerId(0),
                branch: classic_rules::rules::content::PolicyBranchId(liberty as u16),
            },
        )
        .unwrap();

        // One city of a player builds a wonder at a time: the second queue
        // is refused while the first holds it.
        let order = |city| Command::EnqueueProduction {
            player: PlayerId(0),
            city,
            item: ProductionItem::Building(pyramids),
        };
        game.execute(&rules, order(city1)).unwrap();
        assert!(game.execute(&rules, order(city2)).is_err(), "queued in two own cities");
        for _ in 0..600 {
            let done = [city1, city2]
                .iter()
                .all(|c| game.view().auth.cities().get(*c).unwrap().queue.is_empty());
            if done {
                break;
            }
            game.execute(
                &rules,
                Command::EndTurn {
                    player: PlayerId(0),
                },
            )
            .unwrap();
        }
        let owners: Vec<_> = [city1, city2]
            .iter()
            .filter(|c| {
                game.view()
                    .auth
                    .cities()
                    .get(**c)
                    .unwrap()
                    .buildings
                    .contains(&pyramids)
            })
            .copied()
            .collect();
        assert_eq!(
            owners.len(),
            1,
            "wonder must be built exactly once (race: one winner)"
        );
        // The losing city cannot order the wonder again.
        let loser = if owners[0] == city1 { city2 } else { city1 };
        assert!(game
            .execute(
                &rules,
                Command::EnqueueProduction {
                    player: PlayerId(0),
                    city: loser,
                    item: ProductionItem::Building(pyramids),
                },
            )
            .is_err());
        game.validate(&rules).unwrap();
    }
}
